  Fu = `İncelemenin/onaylamanın ve gerekli değişikliklerin yapılabilmesine yeterince zaman tanımak için lütfen arzu ettiğiniz yayın tarihinden en az 7 gün önce sağdaki butonu kullanarak sayfanızı inceleme için gönderin.`,
  Iu = `Sayfanızda yapılması gereken herhangi bir değişiklik olursa, Steam ekibi sizinle Steamworks Destek yardım talebi aracılığıyla irtibata geçer. Sağdaki butona tıklayarak Steamworks Destek yardım talebinizi görüntüleyebilir veya gerekirse buna yorum ekleyebilirsiniz.`,
