  Ru = `İnceleme Talep Et...`,
  zu = `İnceleme Talep Et`,
  Bu = `İndirim sayfası yayınlama onayı için inceleme talebi oluşturur. Bunu, indirim sayfanız son çizimleri ve öne çıkarmak istediğiniz tüm oyunları içerdiğinde yapın.`,
  Vu = `Bu, indirim sayfanızın Valve tarafından incelenmesini talep eden bir Steamworks Destek talebi oluşturur. Bu sadece sayfadaki çizimleriniz ve mesajınız kesinleştikten ve oyun listeniz tamamlandıktan sonra yapılmalıdır.`,
  Hu = `Lütfen etkinlik başlığınızın ve amacınızın sayfanın üst kısmında açıkça belirtildiğinden emin olun. Vitrinler için sayfanızın üst kısmında vitrininizin ne olduğunu ve nasıl çalıştığını açıklayan bir metin bölümüne ihtiyacınız olabilir.`,
  Uu = `İndirim sayfası incelendikten sonra kilitlenecektir. İncelemeden sonra veya etkinlik başladıktan sonra değişiklik yapmanız gerekirse lütfen yorum kısmına bu değişikliklerin neleri içerdiğini ve incelemeden önce neden tamamlanamadığını yazın.`,
  Wu = `İsteğe bağlı: İnceleme ekibi için eklemek istediğiniz bilgiler.`,
  Gu = `Üyelerinin de talebe erişebileceği partnerleri seçin`,
  Ku = `İsteğe bağlı: Seçilirse partnerlerin diğer üyeleri talebe erişebilir ve yanıt verebilir. Varsayılan olarak, oluşturulan talebi yalnızca siz okuyabilir, güncelleyebilir ve yanıtlayabilirsiniz.`,
